extern unsigned char far M[64][64];
extern int far D(int v);
extern int far R8(void);

variants.or_form:
void far f(int x, int y)
{
    int v;
    int bits;

    if (x < 0 || x > 63 || y > 63)
        return;
    v = M[x][y];
    if (v < 0x20)
        return;
    v = v > 0x4d ? 0x2f : 0;
    bits = 0;
    if (y < 2 || D(M[x][y - 1]))
        bits = 1;
    if (x > 62 || D(M[x + 1][y]))
        bits |= 2;
    if (y > 62 || D(M[x][y + 1]))
        bits |= 4;
    if (x < 1 || D(M[x - 1][y]))
        bits |= 8;
    if (bits)
        M[x][y] = bits + v;
    else if (v == 0)
        M[x][y] = R8();
}

